result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/boids.ts", "content": "/**
 * Headless Boids simulation on a 2D torus (wrapping W x H world).
 *
 * Forces (Reynolds' classic three):
 *  - Separation: steer away from close neighbors (short-range, inverse falloff).
 *  - Alignment:  steer toward the mean velocity of neighbors.
 *  - Cohesion:   steer toward the local centroid of neighbors.
 *
 * All distances/deltas use the toroidal (minimum-image) metric. The cohesion
 * target for the *whole flock* metrics uses circular statistics so that a
 * cluster straddling the wrap boundary is handled correctly.
 *
 * Fully deterministic: seeded PRNG for spawn, fixed dt, no Math.random,
 * no reliance on iteration order beyond stable index loops.
 */

export interface BoidsParams {
  seed: number;
  count: number;
  width: number;
  height: number;
  neighborRadius: number;
  dt: number;
  wSep: number;
  wAli: number;
  wCoh: number;
  minSpeed: number;
  maxSpeed: number;
}

export const DEFAULT_PARAMS = {
  count: 60,
  width: 200,
  height: 200,
  neighborRadius: 25,
  dt: 0.05,
  wSep: 9.0,
  wAli: 0.35,
  wCoh: 0.06,
  minSpeed: 1.5,
  maxSpeed: 3.0,
};

/** Small, fast, seedable PRNG (mulberry32). Deterministic across platforms. */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Shortest wrapped delta from a to b on an axis of length L. */
function wrapDelta(d: number, L: number): number {
  let x = d;
  if (x > L / 2) x -= L;
  else if (x < -L / 2) x += L;
  return x;
}

export interface RunResult {
  ticks: number;
  /** FNV-1a hash over quantized positions at every tick — determinism fingerprint. */
  trajectoryHash: string;
  /** Mean pairwise toroidal distance at tick 0. */
  meanPairwiseStart: number;
  /** Mean pairwise toroidal distance at the final tick. */
  meanPairwiseEnd: number;
  /** Smallest pairwise distance observed over the entire run. */
  minPairwiseOverRun: number;
  /** Bounding-circle radius at the final tick. */
  boundingRadiusEnd: number;
}

export class BoidsSim {
  readonly p: BoidsParams;
  tick = 0;

  private xs: Float64Array;
  private ys: Float64Array;
  private vx: Float64Array;
  private vy: Float64Array;

  constructor(opts: Partial<BoidsParams> & { seed: number }) {
    this.p = { ...DEFAULT_PARAMS, ...opts } as BoidsParams;
    const n = this.p.count;
    this.xs = new Float64Array(n);
    this.ys = new Float64Array(n);
    this.vx = new Float64Array(n);
    this.vy = new Float64Array(n);

    const rnd = mulberry32(this.p.seed);
    for (let i = 0; i < n; i++) {
      this.xs[i] = rnd() * this.p.width;
      this.ys[i] = rnd() * this.p.height;
      const angle = rnd() * Math.PI * 2;
      const speed = this.p.minSpeed + rnd() * (this.p.maxSpeed - this.p.minSpeed);
      this.vx[i] = Math.cos(angle) * speed;
      this.vy[i] = Math.sin(angle) * speed;
    }
  }

  /** Advance one fixed-dt step. */
  step(): void {
    const { count, width, height, neighborRadius, dt, wSep, wAli, wCoh, minSpeed, maxSpeed } = this.p;
    const xs = this.xs, ys = this.ys, vx = this.vx, vy = this.vy;
    const R2 = neighborRadius * neighborRadius;
    const invR = 1 / neighborRadius;

    // Per-tick force accumulators (computed from the current state => synchronous update).
    const ax = new Float64Array(count);
    const ay = new Float64Array(count);

    for (let i = 0; i < count; i++) {
      let sepX = 0, sepY = 0;
      let aliX = 0, aliY = 0;
      let cosX = 0, sinX = 0, cosY = 0, sinY = 0; // circular-mean accumulators
      let neighbors = 0;

      const xi = xs[i], yi = ys[i];

      for (let j = 0; j < count; j++) {
        if (j === i) continue;
        const dx = wrapDelta(xs[j] - xi, width);
        const dy = wrapDelta(ys[j] - yi, height);
        const d2 = dx * dx + dy * dy;
        if (d2 > R2 || d2 < 1e-12) continue;
        const d = Math.sqrt(d2);
        neighbors++;

        // Separation: push away with strength that grows as distance shrinks
        // (zero exactly at the neighbor-radius boundary).
        const strength = 1 / d - invR;
        const s = strength / d;
        sepX -= dx * s;
        sepY -= dy * s;

        // Alignment accumulator: sum of neighbor velocities.
        aliX += vx[j];
        aliY += vy[j];

        // Cohesion accumulator via circular statistics on positions.
        const thetaX = (xs[j] / width) * 2 * Math.PI;
        const thetaY = (ys[j] / height) * 2 * Math.PI;
        cosX += Math.cos(thetaX);
        sinX += Math.sin(thetaX);
        cosY += Math.cos(thetaY);
        sinY += Math.sin(thetaY);
      }

      if (neighbors === 0) continue;

      let fx = wSep * sepX;
      let fy = wSep * sepY;

      // Alignment: toward average neighbor velocity.
      const avgVx = aliX / neighbors;
      const avgVy = aliY / neighbors;
      fx += wAli * (avgVx - vx[i]);
      fy += wAli * (avgVy - vy[i]);

      // Cohesion: toward the circular-mean centroid of neighbors.
      let cx = (Math.atan2(sinX, cosX) / (2 * Math.PI)) * width;
      if (cx < 0) cx += width;
      let cy = (Math.atan2(sinY, cosY) / (2 * Math.PI)) * height;
      if (cy < 0) cy += height;
      fx += wCoh * wrapDelta(cx - xi, width);
      fy += wCoh * wrapDelta(cy - yi, height);

      ax[i] = fx;
      ay[i] = fy;
    }

    // Integrate + speed clamp + wrap.
    for (let i = 0; i < count; i++) {
      let nvx = vx[i] + ax[i] * dt;
      let nvy = vy[i] + ay[i] * dt;
      const sp = Math.hypot(nvx, nvy);
      if (sp > maxSpeed) {
        nvx = (nvx / sp) * maxSpeed;
        nvy = (nvy / sp) * maxSpeed;
      } else if (sp < minSpeed && sp > 1e-12) {
        nvx = (nvx / sp) * minSpeed;
        nvy = (nvy / sp) * minSpeed;
      }
      vx[i] = nvx;
      vy[i] = nvy;
      let nx = xs[i] + nvx * dt;
      let ny = ys[i] + nvy * dt;
      nx %= width; if (nx < 0) nx += width;
      ny %= height; if (ny < 0) ny += height;
      xs[i] = nx;
      ys[i] = ny;
    }

    this.tick++;
  }

  /** Toroidal distance between agents i and j. */
  dist(i: number, j: number): number {
    const dx = wrapDelta(this.xs[j] - this.xs[i], this.p.width);
    const dy = wrapDelta(this.ys[j] - this.ys[i], this.p.height);
    return Math.sqrt(dx * dx + dy * dy);
  }

  /** Mean pairwise toroidal distance over all unordered pairs. */
  meanPairwise(): number {
    const n = this.p.count;
    let sum = 0;
    let pairs = 0;
    for (let i = 0; i < n; i++) {
      for (let j = i + 1; j < n; j++) {
        sum += this.dist(i, j);
        pairs++;
      }
    }
    return pairs === 0 ? 0 : sum / pairs;
  }

  /** Minimum pairwise toroidal distance (Infinity for count < 2). */
  minPairwise(): number {
    const n = this.p.count;
    let m = Infinity;
    for (let i = 0; i < n; i++) {
      for (let j = i + 1; j < n; j++) {
        const d = this.dist(i, j);
        if (d < m) m = d;
      }
    }
    return m;
  }

  /**
   * Bounding-circle radius: max toroidal distance from the population's
   * circular-mean center. Robust to clusters straddling the wrap boundary.
   */
  boundingRadius(): number {
    const n = this.p.count;
    const { width, height } = this.p;
    let cosX = 0, sinX = 0, cosY = 0, sinY = 0;
    for (let i = 0; i < n; i++) {
      cosX += Math.cos((this.xs[i] / width) * 2 * Math.PI);
      sinX += Math.sin((this.xs[i] / width) * 2 * Math.PI);
      cosY += Math.cos((this.ys[i] / height) * 2 * Math.PI);
      sinY += Math.sin((this.ys[i] / height) * 2 * Math.PI);
    }
    let cx = (Math.atan2(sinX, cosX) / (2 * Math.PI)) * width;
    if (cx < 0) cx += width;
    let cy = (Math.atan2(sinY, cosY) / (2 * Math.PI)) * height;
    if (cy < 0) cy += height;

    let r = 0;
    for (let i = 0; i < n; i++) {
      const dx = wrapDelta(this.xs[i] - cx, width);
      const dy = wrapDelta(this.ys[i] - cy, height);
      const d = Math.sqrt(dx * dx + dy * dy);
      if (d > r) r = d;
    }
    return r;
  }

  /** FNV-1a over quantized agent positions at the current tick. */
  snapshotHash(prev = 0x811c9dc5): number {
    let h = prev >>> 0;
    const q = 1000; // 0.001-unit quantization
    for (let i = 0; i < this.p.count; i++) {
      const qx = Math.round(this.xs[i] * q) | 0;
      const qy = Math.round(this.ys[i] * q) | 0;
      h ^= qx & 0xff; h = Math.imul(h, 16777619) >>> 0;
      h ^= (qx >>> 8) & 0xff; h = Math.imul(h, 16777619) >>> 0;
      h ^= (qx >>> 16) & 0xff; h = Math.imul(h, 16777619) >>> 0;
      h ^= qy & 0xff; h = Math.imul(h, 16777619) >>> 0;
      h ^= (qy >>> 8) & 0xff; h = Math.imul(h, 16777619) >>> 0;
      h ^= (qy >>> 16) & 0xff; h = Math.imul(h, 16777619) >>> 0;
    }
    return h >>> 0;
  }

  /** Run `ticks` fixed-dt steps, tracking trajectory hash and min separation. */
  run(ticks: number): RunResult {
    const startMean = this.meanPairwise();
    let hash = 0x811c9dc5;
    hash = this.snapshotHash(hash); // include initial state
    let minDist = this.minPairwise();
    for (let t = 0; t < ticks; t++) {
      this.step();
      hash = this.snapshotHash(hash);
      const m = this.minPairwise();
      if (m < minDist) minDist = m;
    }
    return {
      ticks,
      trajectoryHash: (hash >>> 0).toString(16).padStart(8, "0"),
      meanPairwiseStart: startMean,
      meanPairwiseEnd: this.meanPairwise(),
      minPairwiseOverRun: minDist,
      boundingRadiusEnd: this.boundingRadius(),
    };
  }
}
