result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/tests/boids.test.ts", "content": "import { describe, expect, it } from "vitest";
import { BoidsSim, DEFAULT_PARAMS } from "../src/boids";

const SEEDS = [1, 2, 3, 4, 5];
const TICKS = 500;

function runSim(seed: number, overrides: Partial<{ wSep: number; wAli: number; wCoh: number }> = {}) {
  const sim = new BoidsSim({ seed, ...overrides });
  return { sim, result: sim.run(TICKS) };
}

describe("boids on a torus (60 agents, 200x200, neighbor radius 25, dt=0.05)", () => {
  it("flocking: mean pairwise distance shrinks after 500 ticks and separation keeps agents apart", () => {
    for (const seed of SEEDS) {
      const { result } = runSim(seed);
      // Flocking compacts the population.
      expect(result.meanPairwiseEnd).toBeLessThan(result.meanPairwiseStart);
      // Separation works: no two agents ever come closer than 1.0 units.
      expect(result.minPairwiseOverRun).toBeGreaterThan(1.0);
    }
  });

  it("cohesion matters: bounding-circle radius at tick 500 is larger without cohesion", () => {
    for (const seed of SEEDS) {
      const withCohesion = runSim(seed).result.boundingRadiusEnd;
      const withoutCohesion = runSim(seed, { wCoh: 0 }).result.boundingRadiusEnd;
      expect(withoutCohesion).toBeGreaterThan(withCohesion);
    }
  });

  it("deterministic per seed: identical trajectory hashes across runs, distinct across seeds", () => {
    const hashes: string[] = [];
    for (const seed of SEEDS) {
      const a = runSim(seed).result.trajectoryHash;
      const b = runSim(seed).result.trajectoryHash;
      expect(a).toBe(b); // same seed => bit-identical trajectory
      hashes.push(a);
    }
    expect(new Set(hashes).size).toBe(SEEDS.length); // different seeds => different trajectories
  });

  it("sanity: parameters match spec and initial state is seeded-reproducible", () => {
    expect(DEFAULT_PARAMS.count).toBe(60);
    expect(DEFAULT_PARAMS.width).toBe(200);
    expect(DEFAULT_PARAMS.height).toBe(200);
    expect(DEFAULT_PARAMS.neighborRadius).toBe(25);

    const s1a = new BoidsSim({ seed: 42 });
    const s1b = new BoidsSim({ seed: 42 });
    expect(s1a.snapshotHash()).toBe(s1b.snapshotHash());
  });
});
"})
print(result)

